"uri":"http://data.europa.eu/esco/skill/7f0aa0f9-ee9e-47f9-806d-22de04cf5148","category":"H1","reason":"É uma especialidade científica sobre fármacos, neurotransmissores e sistema nervoso.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/7f0b1a66-ebaf-4c8a-b606-4c1844eb692e","category":"H3","reason":"Consiste na prática técnica de garantia da qualidade de sistemas informáticos.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/7f0f5ec6-6874-4428-97b4-a7e373410806","category":"H4","reason":"É uma atividade estruturada de recrutamento e seleção de candidatos para audições.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/7f107a85-d6ac-410f-a995-d635c5aa418b","category":"H1","reason":"É conhecimento técnico de materiais metálicos, suas especificações, aplicações e comportamento em fabrico.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/7f11e509-2551-4628-ba8b-b80b1d48f12b","category":"H3","reason":"É um procedimento técnico de produção têxtil para enrolar cordões de fibra em tubos.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/7f18039d-dfae-471b-9daa-507f6b2d2842","category":"H1","reason":"Planeamento urbano é um domínio técnico-profissional interdisciplinar de conceção e ordenamento do ambiente urbano, não apenas a gestão de uma operação.","certainty":"adjudicated_high"},{"uri":"http://data.europa.eu/esco/skill/7f18c3a2-f1ce-4db2-a354-9417691b5a43","category":"H3","reason":"É uma prática estruturada de documentação operacional e elaboração de relatórios de produção.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/7f1a7abb-9208-48b7-8b84-2c1f283a50a0","category":"H1","reason":"É conhecimento técnico de redes e telecomunicações relativo à transferência eficiente de chamadas.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/7f207dfb-9977-4488-ae52-9b00a897e620","category":"H3","reason":"É uma prática especializada de direção musical de solistas no contexto de um conjunto.","certainty":"medium"},{"uri":"http://data.europa.eu/esco/skill/7f27f1ff-2e17-4b69-990e-c23334478313","category":"H1","reason":"É conhecimento especializado sobre avaliação e documentação de riscos e ameaças de segurança.","certainty":"medium"},{"uri":"http://data.europa.eu/esco/skill/7f2afce6-e98b-4bbe-8441-d52b45e28ab8","category":"H1","reason":"É conhecimento especializado de regras e requisitos regulatórios aplicáveis às telecomunicações.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/7f2b7c15-1e2d-44fe-a66f-28691f627c00","category":"H3","reason":"Consiste num procedimento operacional de descarregar, preparar e transferir madeira para secagem.","certainty":"high"},{"uri":"http://data.europa.eu/esco/skill/7f2c62b0-928a-4da2-a578-674940a14063","category":"H1","reason":"Refere-se ao conhecimento técnico das capacidades de elevação e limites operacionais de gruas.","certainty":"high"}]$m82_json$::jsonb;
  v_found integer;
begin
  select count(distinct item.uri) into v_found
  from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
  join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
  join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
  join public.knowledge_source_versions source_version on source_version.id = mapping.source_version_id
    and source_version.external_version = '1.2.1' and source_version.import_status = 'published'
  join public.knowledge_concepts concept on concept.id = mapping.concept_id
    and concept.scope = 'global' and concept.status = 'approved'
    and concept.concept_type not in ('occupation','certification');
  if v_found <> jsonb_array_length(v_input) then
    raise exception 'M82_ESCO_MAPPING_MISMATCH: found %, expected %', v_found, jsonb_array_length(v_input);
  end if;
  if exists (
    select mapping.concept_id
    from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
    join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
    join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
    group by mapping.concept_id having count(distinct item.category)>1
  ) then raise exception 'M82_ESCO_CANONICAL_CLASS_CONFLICT'; end if;
  insert into public.knowledge_competency_classifications
    (concept_id, subgroup_id, version, taxonomy_version, method, provenance)
  select distinct on (concept.id)
    concept.id, subgroup.id,
    coalesce((select max(history.version)+1 from public.knowledge_competency_classifications history
      where history.concept_id=concept.id),1),
    'competency-taxonomy-2.0.0', 'ai_assisted',
    jsonb_build_object('source','ESCO','sourceVersion','1.2.1','sourceURI',item.uri,
      'sourceHash','1b5e5356d4037cdd5c938131b385b9059a1e5f256ca621e8372b6633ec9aea80',
      'classifierVersion','prisma-competency-classification-1.1.0',
      'model','gpt-5.6-terra', 'reason',item.reason,'certainty',item.certainty,
      'agreement','M8.2-1.0.0')
  from jsonb_to_recordset(v_input) as item(uri text, category text, reason text, certainty text)
  join public.knowledge_external_mappings mapping on mapping.external_uri = item.uri
  join public.knowledge_sources source on source.id = mapping.source_id and source.name = 'ESCO'
  join public.knowledge_source_versions source_version on source_version.id = mapping.source_version_id
    and source_version.external_version = '1.2.1' and source_version.import_status = 'published'
  join public.knowledge_concepts concept on concept.id = mapping.concept_id
    and concept.scope = 'global' and concept.status = 'approved'
    and concept.concept_type not in ('occupation','certification')
  join public.competency_subgroups subgroup on subgroup.code=item.category and subgroup.scope='global' and subgroup.status='active'
  where not exists (select 1 from public.knowledge_competency_classifications current_class
    where current_class.concept_id=concept.id and current_class.is_current)
  order by concept.id,item.uri;
end $m82$;
